import {createModel,TYPES,GATES,esc,entityHref,chapterHref} from './model.js';

const $=id=>document.getElementById(id);
const store={get(k,f){try{return JSON.parse(localStorage.getItem('stormlight.v3.'+k))??f}catch{return f}},set(k,v){try{localStorage.setItem('stormlight.v3.'+k,JSON.stringify(v));return true}catch{return false}}};
const data=await fetch(new URL('./data.json', import.meta.url)).then(r=>{if(!r.ok)throw new Error('Could not load reference data.');return r.json()}).catch(e=>{$('main').textContent=e.message;throw e});
const model=createModel(data,Math.min(7,Math.max(0,Number(store.get('gate',4))||0)));
const state={type:'all',book:'all',query:'',page:1,mode:'story',plane:'Physical',mapAllLabels:false,route:'',focus:'character:kaladin',chapterBook:'TWoK',chapterQuery:'',onlyAnchors:false,relationKind:'all',read:new Set(store.get('read',[])),saved:new Set(store.get('saved',[])),notes:store.get('notes',{}),returnFocus:null};
const titles={home:'Overview',explore:'Encyclopedia',timeline:'Chronology',chapters:'Books & chapters',map:'Places & routes',connections:'Connections',status:'Status ledger',saved:'Reading desk',sources:'Sources & coverage'};
const trim=(s,n=175)=>String(s||'').length>n?String(s).slice(0,n-1)+'…':s||'';
const badge=(t,cls='')=>`<span class="badge ${cls}">${esc(t)}</span>`;
const bookName=abbr=>model.book(abbr)?.title||abbr;
const boundaryName=()=>model.gate?data.books.find(b=>b.gate===model.gate)?.title:'No books yet';
const bookOptions=(value='all',allowFuture=false)=>`<option value="all">All available books</option>`+[...data.books,...data.supplements.map(s=>({...s,gate:2}))].filter(b=>allowFuture||b.gate<=model.gate).map(b=>`<option value="${b.abbr}" ${b.abbr===value?'selected':''}>${esc(b.title)}</option>`).join('');
const head=(eyebrow,title,description)=>`<header class="head"><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></header>`;
const empty=(s='No entries match. Try changing your filters.')=>`<div class="empty">${esc(s)}</div>`;
const href=(p)=>entityHref(p.type,p.id);
const safeURL=u=>/^https:\/\//.test(u||'')?esc(u):'#';
const external=(u,label)=>`<a class="external" href="${safeURL(u)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`;
const progress=abbr=>{const cs=data.chapters.filter(c=>c.book===abbr);const done=cs.filter(c=>state.read.has(c.key)).length;return {done,total:cs.length,pct:cs.length?Math.round(done/cs.length*100):0}};
const links=(ids,type)=>[...new Set(ids||[])].map(id=>{const e=model.resolve(id,type),p=e&&model.profile(e.key);return p?`<a class="entity-link" href="${href(p)}">${esc(p.name)}</a>`:''}).join('');
const pcard=p=>`<article class="card linked"><div class="type">${esc(p.type)}${p.full&&p.raw.kind?' · '+esc(p.raw.kind):''}</div><h3><a href="${href(p)}">${esc(p.name)}</a></h3><p>${esc(trim(p.summary,210))}</p>${p.status?`<div class="status">${esc(p.status)}</div>`:''}<div class="card-footer">${p.books.map(x=>badge(x)).join('')}${!p.full?badge('Safe facts only','gold'):''}</div></article>`;
const eventCard=e=>`<article class="event card"><div class="meta-line">${badge(e.book||'History','gold')}${e.chapter?badge(e.chapter):''}${badge(e.confidence||'uncertain',e.confidence==='high'?'teal':'warn')}</div><h3 style="margin:13px 0 9px"><a href="${entityHref('event',e.id)}">${esc(e.title)}</a></h3><div class="small muted">${esc(e.dateLabel||e.chronology)}</div><p>${esc(e.summary)}</p><div class="card-footer">${links((e.characters||[]).slice(0,5),'character')}</div></article>`;
function paginate(items,render,size=30){const total=Math.max(1,Math.ceil(items.length/size));state.page=Math.max(1,Math.min(state.page,total));return render(items.slice((state.page-1)*size,state.page*size))+ (total>1?`<div class="pagination"><button class="btn" data-page="${state.page-1}" ${state.page===1?'disabled':''}>← Previous</button><span class="small muted">${state.page} / ${total} · ${items.length} results</span><button class="btn" data-page="${state.page+1}" ${state.page===total?'disabled':''}>Next →</button></div>`:'');}
function home(){
 const counts=TYPES.map(t=>[t,model.list(t).length]);
 const major=model.list('character').filter(p=>p.full&&p.raw.tags?.includes('major')).slice(0,6);
 return `<section class="hero"><svg class="hero-art" viewBox="0 0 440 300" aria-hidden="true"><g fill="none" stroke="#d6bd87"><circle cx="280" cy="150" r="118"/><circle cx="280" cy="150" r="95"/><circle cx="280" cy="150" r="50"/><path d="M280 10v280M140 150h280M180 50l200 200M180 250L380 50M230 40L330 260M170 100l220 100M170 200L390 100M230 260L330 40"/><path d="M280 28l26 76 70-37-37 70 69 13-69 13 37 70-70-37-26 76-26-76-70 37 37-70-69-13 69-13-37-70 70 37z"/></g></svg><div class="hero-content"><div class="eyebrow">A FIELD GUIDE TO THE STORMLIGHT ARCHIVE</div><h1>Find your way<br>back to Roshar.</h1><p>Follow a character. Revisit a chapter. Connect the pieces. Explore the published saga with a spoiler boundary you control.</p><div class="actions"><a class="btn primary" href="#/explore">Explore the archive <span aria-hidden="true">↗</span></a><a class="btn ghost" href="#/timeline">Follow the chronology</a></div></div></section>
 <div class="meta-line">Reveals through ${esc(boundaryName())} · ${model.gate===7?'All published core novels unlocked':'Change “I have finished” to unlock later books'}</div>
 <div class="stats" style="margin-top:20px">${counts.map(([t,n])=>`<a class="stat" href="#/explore?type=${t}"><strong>${n}</strong><span>${t==='magic'?'Magic systems':t+'s'}</span></a>`).join('')}<a class="stat" href="#/timeline"><strong>${model.events().length}</strong><span>Story anchors</span></a></div>
 <div class="section-head"><h2>The reading journey</h2><a href="#/chapters">Open books & chapters →</a></div><div class="books">${data.books.map(b=>{const p=progress(b.abbr);return `<a class="book ${b.gate>model.gate?'locked':''}" href="#/chapters?book=${b.abbr}"><div class="book-no">${b.seriesOrder%1?'INTERLUDE NOVELLA':'BOOK '+b.seriesOrder}</div><h3>${esc(b.title)}</h3><small>${b.year} · ${b.gate>model.gate?'Spoilers locked':b.abbr}</small><div class="progress"><i style="width:${p.pct}%"></i></div><small>${p.done} / ${p.total} sections marked read</small></a>`}).join('')}</div>
 <div class="section-head"><h2>Where the cast stands</h2><a href="#/explore?type=character">All characters →</a></div>${major.length?`<div class="grid">${major.map(pcard).join('')}</div>`:empty('Choose a completed book above to reveal characters and status records.')}
 <div class="notice"><strong>Your spoiler boundary follows you.</strong> Search, profiles, relationship links, event anchors and maps use the selected completed-book boundary. Chapter selection does not advance it. Reading progress and notes are saved in this browser.</div>
 <div class="split"><article class="card"><div class="eyebrow">PAST THE MAIN NOVELS</div><h2>The smaller journeys</h2><p>Edgedancer and Dawnshard appear in the main sequence. Elsecaller and King Lopen are cataloged with their own source and coverage notes.</p><a href="#/chapters?book=supplements" class="btn ghost">View side stories</a></article><article class="card"><div class="eyebrow">READ WITH CONTEXT</div><h2>A map, not a concordance</h2><p>Major arcs and outcomes are linked to chapters. Approximate dates and inherited references are labeled. A chapter in the index does not imply a recap of every scene.</p><a href="#/sources" class="btn ghost">Review sources & coverage</a></article></div>`;
}
function explorer(params){
 const t=params.get('type');if(TYPES.includes(t))state.type=t;
 const list=model.list(state.type,state.query,state.book);
 return head('PEOPLE · PLACES · POWERS','The encyclopedia','Open a record to follow its status, chapter anchors, and connections. Only facts allowed by your spoiler boundary are searchable.')+`<div class="tabs">${['all',...TYPES].map(t=>`<button class="chip ${state.type===t?'active':''}" data-type="${t}">${t==='all'?'Everything':t==='magic'?'Magic':t[0].toUpperCase()+t.slice(1)+'s'}</button>`).join('')}</div><div class="filters"><input id="entity-query" class="field" type="search" placeholder="Filter names, aliases, descriptions…" aria-label="Filter encyclopedia" value="${esc(state.query)}"><select id="entity-book" aria-label="Filter by book">${bookOptions(state.book)}</select><span class="count">${list.length} entries</span></div>`+paginate(list,x=>x.length?`<div class="grid">${x.map(pcard).join('')}</div>`:empty());
}
function timeline(){
 let es=model.events().filter(e=>(state.book==='all'||e.book===state.book)&&(!state.query||[e.title,e.summary,e.dateLabel,...e.characters||[]].join(' ').toLowerCase().includes(state.query.toLowerCase())));
 if(state.mode==='reading')es.sort((a,b)=>(GATES[a.book]||0)-(GATES[b.book]||0)||chapterOrdinal(a)-chapterOrdinal(b)||a.sort-b.sort);
 else es.sort((a,b)=>(b.history?1:0)-(a.history?1:0)||a.sort-b.sort);
 if(state.mode==='reverse')es.reverse();
 return head('READING ORDER & WORLD HISTORY','A story told across time','Revisit the decisive moments, from ancient history to the latest available ending. Parallel fronts and flashbacks are labeled rather than assigned false precision.')+`<div class="filters"><select id="timeline-mode" aria-label="Chronology order"><option value="story" ${state.mode==='story'?'selected':''}>In-world: history, then story anchors</option><option value="reading" ${state.mode==='reading'?'selected':''}>Book & chapter reveal order</option><option value="reverse" ${state.mode==='reverse'?'selected':''}>Reverse anchor order</option></select><select id="timeline-book" aria-label="Filter chronology by book">${bookOptions(state.book)}</select><input id="timeline-query" class="field" type="search" aria-label="Filter timeline" placeholder="Search events, names…" value="${esc(state.query)}"><span class="count">${es.length} events</span></div><div class="notice"><strong>Chronology confidence.</strong> ${esc(data.meta.chronology)} The in-world view groups historical events first; order inside undated groups is approximate. Confidence badges describe the event, not an exact date.</div>`+paginate(es,x=>x.length?`<div class="timeline">${x.map(eventCard).join('')}</div>`:empty(),24);
}
function chapterOrdinal(e){if(typeof e.chapter==='number')return e.chapter;const c=String(e.chapter||'');if(/prelude/i.test(c))return -2;if(/prologue/i.test(c))return -1;if(/postlude/i.test(c))return 2001;if(/epilogue/i.test(c))return 2000;return Number(c.match(/(?:Ch(?:apter)?\.?\s*)(\d+)/i)?.[1]||e.sort);}
function chapterList(params){
 const b=params.get('book');if(b&&([...data.books.map(x=>x.abbr),'supplements'].includes(b)))state.chapterBook=b;
 const book=model.book(state.chapterBook),cs=data.chapters.filter(c=>c.book===state.chapterBook).sort((a,b)=>a.number-b.number),p=progress(state.chapterBook);
 const menu=`<div class="book-select">${data.books.map(x=>`<button data-chapter-book="${x.abbr}" class="${x.abbr===state.chapterBook?'active':''}">${esc(x.title)}<small>${x.gate>model.gate?'Spoilers locked':progress(x.abbr).done+'/'+x.chapterCount+' marked read'}</small></button>`).join('')}<button data-chapter-book="supplements" class="${state.chapterBook==='supplements'?'active':''}">Side stories & connections<small>Story Deck + other Cosmere works</small></button></div>`;
 let body;
 if(state.chapterBook==='supplements')body=supplements();
 else if(book.gate>model.gate)body=`<div class="card"><div class="eyebrow">BOOK ${book.seriesOrder} · ${book.year}</div><h2>${esc(book.title)}</h2><p>The section index and story details are locked at your current spoiler boundary.</p><div class="notice">Change “I have finished” above after reading this book. Opening its catalog entry does not reveal its plot.</div></div>`;
 else {const filtered=cs.filter(c=>(!state.onlyAnchors||c.anchors?.length)&&(!state.chapterQuery||[c.label,c.arc,c.arcSummary].join(' ').toLowerCase().includes(state.chapterQuery.toLowerCase())));body=`<div class="card" style="margin-bottom:20px"><div class="eyebrow">${esc(book.scope)} · ${book.year}</div><h2>${esc(book.title)}</h2><p>${esc(book.summary)}</p><div class="small muted">${esc(book.chronology)}</div><div class="progress"><i style="width:${p.pct}%"></i></div><div class="meta-line">${p.done} of ${p.total} sections marked read · ${p.pct}%</div></div><div class="filters"><input id="chapter-query" class="field" aria-label="Filter chapters" type="search" value="${esc(state.chapterQuery)}" placeholder="Filter chapter or arc…"><label class="small muted"><input type="checkbox" id="anchors-only" ${state.onlyAnchors?'checked':''}> Anchored sections only</label><span class="count">${filtered.length} sections</span></div><div class="chapters">${filtered.map(c=>`<article class="chapter ${state.read.has(c.key)?'read':''}"><a href="${chapterHref(c.book,c.number)}">${esc(c.label)}</a><small>${c.anchors?.length?c.anchors.length+' story anchors':esc(c.coverage)}</small><button class="mark" data-read="${esc(c.key)}" aria-label="${state.read.has(c.key)?'Mark unread':'Mark read'}: ${esc(c.label)}">${state.read.has(c.key)?'✓':'○'}</button></article>`).join('')}</div>`;}
 return head('THE TEXT, REVISITED','Books & chapters','Navigate the complete numbered-chapter index and interludes. Curated arc summaries and event anchors are separate from index-only records.')+`<div class="chapter-layout">${menu}<section>${body}</section></div>`;
}
function supplements(){
 return `<h2>Stormlight side stories</h2><div class="notice">These optional stories are set during Words of Radiance. Their plot details unlock at that completed-book boundary; some scene-by-scene references remain unavailable.</div><div class="grid">${data.supplements.map(s=>`<article class="card"><div class="type">${esc(s.kind||'Stormlight short story')}</div><h3>${esc(s.title)}</h3><p>${model.gate>=2?esc(s.summary):'Plot details hidden until Words of Radiance is completed.'}</p>${model.gate>=2?`<div class="rows">${(s.events||[]).map(e=>`<a class="row" href="${entityHref('event',e.id)}"><div class="grow"><b>${esc(e.title)}</b><small>${esc(e.summary)}</small></div></a>`).join('')}</div>`:''}${model.gate>=2?(s.facts||[]).map(f=>`<p>${esc(typeof f==='string'?f:f.text)}</p>`).join(''):''}<div class="coverage-note">${esc(s.coverage||'Catalog and broad premise; detailed chapter coverage incomplete.')}</div><div class="card-footer">${(s.sources||[]).map(u=>external(typeof u==='string'?(data.sources.find(x=>x.id===u)?.url||u):u.url,'Story source')).join('')}</div></article>`).join('')}</div><div class="section-head"><h2>Across the Cosmere</h2></div><p class="small muted">Other Cosmere books are a reading catalog, not full plot coverage. Connection descriptions unlock only at the final Stormlight boundary because they can reveal cross-world identities.</p><div class="rows">${data.cosmereBooks.map(b=>`<div class="row"><div class="grow"><b>${esc(b.title)}</b><small>${esc(b.series)} · ${b.year}${model.gate===7?' · '+esc(b.connection):''}</small></div></div>`).join('')}</div><div class="notice"><strong>Not yet published:</strong> Horneater and Stormlight novels 6–10 are excluded from story coverage. Publication plans may change.</div>`;
}
function mapView(){
 const locs=model.list('location').filter(p=>p.raw.plane===state.plane&&(state.book==='all'||p.books.includes(state.book)));
 const routes=state.route?model.routePoints(state.route,state.plane):[];
 const routeChars=model.list('character').filter(p=>model.routePoints(p.id,state.plane).length>1);
 const planes=[...new Set(data.entities.filter(e=>e.type==='location').map(e=>e.versions[0].data.plane))];
 return head('THE GEOGRAPHY OF A JOURNEY','Places & routes','An original coordinate schematic for navigation. Positions come from the recovered atlas and indicate broad relative placement; they are not surveyed locations or an official map.')+`<div class="filters"><select id="map-plane" aria-label="Map realm">${planes.map(p=>`<option ${p===state.plane?'selected':''}>${esc(p)}</option>`).join('')}</select><select id="map-book" aria-label="Filter map by book">${bookOptions(state.book)}</select><label class="small muted"><input type="checkbox" id="map-labels" ${state.mapAllLabels?'checked':''}> All labels</label><select id="map-route" aria-label="Character route"><option value="">No character route</option>${routeChars.map(p=>`<option value="${p.id}" ${state.route===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="map-wrap"><svg class="map-svg" viewBox="0 0 1000 650" role="img" aria-label="${esc(state.plane)} approximate location schematic">${[100,200,300,400,500,600,700,800,900].map(x=>`<path class="gridline" d="M${x} 30V620"/>`).join('')}${[100,200,300,400,500,600].map(y=>`<path class="gridline" d="M40 ${y}H960"/>`).join('')}<text x="45" y="45" style="fill:#d6bd87;font-size:13px;letter-spacing:3px">${esc(state.plane.toUpperCase())}</text><text x="45" y="65" style="font-size:9px;fill:#758b99">SCHEMATIC · NOT TO SCALE</text>${routes.length>1?`<polyline class="route" points="${routes.map(p=>`${p.location.raw.x},${p.location.raw.y}`).join(' ')}"/>`:''}${locs.filter(p=>Number.isFinite(p.raw.x)&&Number.isFinite(p.raw.y)).map(p=>`<a href="${href(p)}" aria-label="Open ${esc(p.name)}"><title>${esc(p.name)}</title><circle cx="${p.raw.x}" cy="${p.raw.y}" r="4" fill="#8ab8ba" stroke="#0c141d" stroke-width="2"/>${state.mapAllLabels||['city','town'].includes(p.raw.scale)||['urithiru','shinovar','shattered-plains','aimia','lasting-integrity'].includes(p.id)?`<text x="${p.raw.x+8}" y="${p.raw.y-7}">${esc(p.name)}</text>`:''}</a>`).join('')}</svg><div class="map-caption">${locs.length} locations · Labels may overlap at local scales; use the accessible location list below. Routes join selected story anchors in approximate sequence and omit unrecorded travel.</div></div>${routes.length?`<div class="section-head"><h2>Route anchors</h2></div><div class="rows">${routes.map((p,i)=>`<a class="row" href="${entityHref('event',p.event.id)}"><span class="badge gold">${i+1}</span><div class="grow"><b>${esc(p.location.name)}</b><small>${esc(p.event.book)} · ${esc(p.event.chapter||p.event.dateLabel)}</small></div><span class="arrow">→</span></a>`).join('')}</div>`:''}<div class="section-head"><h2>Location index</h2><span class="count">${locs.length} places</span></div><div class="grid">${locs.map(pcard).join('')}</div><div class="notice">Reliable geographic context: ${external('https://www.brandonsanderson.com/pages/the-stormlight-archive-series','Official book and artwork page')} · ${external('https://roshar.17thshard.com/','17th Shard interactive map')}. External sites use their own spoiler rules; official art is linked rather than reproduced.</div>`;
}
function connections(){
 const focus=model.profile(state.focus)||model.list('character')[0]||model.list()[0];
 if(!focus)return head('PEOPLE & THEIR TIES','Connections','Choose a completed book to reveal relationship records.')+empty('No safe relationship records yet.');
 state.focus=focus.key;
 const all=model.connections(focus.key),kinds=[...new Set(all.map(e=>e.kind))].sort(),edges=all.filter(e=>state.relationKind==='all'||e.kind===state.relationKind);
 const shown=edges.slice(0,12),cx=400,cy=230;
 return head('FOLLOW THE CONNECTIONS','Nothing happens alone.','Explore relationships, organizational membership and profile associations. Labels distinguish dated story facts from a catalog connection.')+`<div class="filters"><select id="connection-focus" aria-label="Connection focus">${model.list().map(p=>`<option value="${p.key}" ${p.key===focus.key?'selected':''}>${esc(p.name)} · ${p.type}</option>`).join('')}</select><select id="relation-kind" aria-label="Relationship type"><option value="all">All connection types</option>${kinds.map(k=>`<option ${state.relationKind===k?'selected':''}>${esc(k)}</option>`).join('')}</select><span class="count">${edges.length} connections</span></div><svg class="connection-graph" viewBox="0 0 800 460" role="img" aria-label="Connections around ${esc(focus.name)}">${shown.map((e,i)=>{const a=i/shown.length*Math.PI*2,x=cx+285*Math.cos(a),y=cy+175*Math.sin(a);return `<line x1="${cx}" y1="${cy}" x2="${x}" y2="${y}"/><a href="${href(e.target)}"><circle cx="${x}" cy="${y}" r="17"/><text x="${x}" y="${y+34}" text-anchor="middle">${esc(trim(e.target.name,23))}</text></a>`}).join('')}<a href="${href(focus)}"><circle class="focus" cx="400" cy="230" r="38"/><text x="400" y="289" text-anchor="middle" style="fill:#d6bd87">${esc(focus.name)}</text></a></svg><div class="coverage-note">Diagram displays the first ${shown.length} connections. The complete accessible list follows.</div><div class="section-head"><h2>${esc(focus.name)}’s connections</h2></div><div class="edge-list">${edges.map(e=>`<article class="edge"><span class="badge">${esc(e.label)}</span> <a href="${href(e.target)}">${esc(e.target.name)}</a>${e.summary?`<p>${esc(e.summary)}</p>`:''}<small class="muted">${esc(e.evidence)}</small></article>`).join('')||empty()}</div>`;
}

function statusLedger(){
 const list=model.list('character',state.query).filter(p=>p.facts.length);
 return head('A SNAPSHOT AT YOUR BOUNDARY','Status ledger','The last recorded status for each character at your selected completed-book boundary. A past record is not proof of a later fate; exact locators are shown when verified.')+`<div class="filters"><input id="status-query" class="field" aria-label="Filter character statuses" type="search" placeholder="Filter names or status facts…" value="${esc(state.query)}"><span class="count">${list.length} dated records</span></div>`+paginate(list,rows=>rows.length?`<div class="table-wrap"><table><thead><tr><th>Character</th><th>Last recorded status</th><th>Reference</th></tr></thead><tbody>${rows.map(p=>{const f=p.facts.at(-1);return `<tr><td><a class="external" href="${href(p)}">${esc(p.name)}</a></td><td>${esc(f.text)}${f.certainty&&f.certainty!=='confirmed'?' '+badge(f.certainty,'warn'):''}</td><td>${esc(f.locator||'Exact chapter unverified')}</td></tr>`}).join('')}</tbody></table></div>`:empty('No dated statuses are available at this boundary.'));
}

function saved(){
 const records=[...state.saved].map(k=>model.profile(k)).filter(Boolean),notes=Object.entries(state.notes).filter(([k,v])=>v&&model.profile(k));
 return head('YOUR READING DESK','Leave yourself a trail.','Bookmarks, notes and chapter progress stay in this browser. Export a backup to move them to another device.')+`<div class="actions"><button class="btn" data-export>Export reading backup</button><label class="btn">Import backup<input id="import-backup" type="file" accept="application/json" class="sr-only"></label></div><div class="section-head"><h2>Bookmarked records</h2></div>${records.length?`<div class="grid">${records.map(pcard).join('')}</div>`:empty('Use “Bookmark” inside any encyclopedia record. Later-book bookmarks stay hidden at earlier boundaries.')}<div class="section-head"><h2>Your notes</h2></div><div class="rows">${notes.map(([k,n])=>{const p=model.profile(k);return `<a class="row" href="${href(p)}"><div class="grow"><b>${esc(p.name)}</b><small>${esc(trim(n,180))}</small></div><span class="arrow">→</span></a>`}).join('')||'<div class="row"><span class="muted small">No notes at this boundary.</span></div>'}</div><div class="section-head"><h2>Chapter progress</h2></div><div class="rows">${data.books.map(b=>{const p=progress(b.abbr);return `<a class="row" href="#/chapters?book=${b.abbr}"><div class="grow"><b>${esc(b.title)}</b><div class="progress"><i style="width:${p.pct}%"></i></div></div><span class="small muted">${p.done}/${p.total}</span></a>`}).join('')}</div>`;
}
function sources(){
 return head('TRUST, CONTEXT & COVERAGE','Know what you’re looking at.','The reference combines your two existing atlases with separately sourced additions. Broad coverage is not a guarantee of every scene, every name, or every mention.')+`<div class="notice"><strong>Published Stormlight scope:</strong> ${esc(data.meta.scope)} The series is planned to continue; “all books” here means currently published Stormlight novels and novellas, plus the cataloged short stories.</div><div class="table-wrap"><table><thead><tr><th>Work</th><th>Indexed sections</th><th>Coverage</th></tr></thead><tbody>${data.books.map(b=>`<tr><td>${esc(b.title)}</td><td>${b.chapterCount}</td><td>${esc(b.coverage)}</td></tr>`).join('')}${data.supplements.map(s=>`<tr><td>${esc(s.title)}</td><td>Whole-story reference</td><td>${esc(s.coverage||'Catalog and broad premise; detailed index unavailable')}</td></tr>`).join('')}</tbody></table></div><div class="split" style="margin-top:24px"><article class="card"><h2>Reconciliation</h2><p>${esc(data.meta.reconciliation)}</p>${model.gate>=4?'<p>Selected inherited anchors were corrected: assassination year 1167; Dalinar/Navani wedding OB 4; Szeth’s restoration WoR 88; Jezrien’s death OB 121; chasmfiend hunt TWoK 13. Missing early-book interludes were indexed.</p>':'<p>Selected dates and chapter anchors were corrected against sources; missing early-book interludes were indexed. Plot-specific correction details unlock after Oathbringer.</p>'}</article><article class="card"><h2>Spoiler handling</h2><p>${esc(data.meta.spoilers)}</p><p>Default boundary: Oathbringer. Profiles from later snapshots cannot appear in earlier search results. External source pages may contain unrestricted spoilers.</p></article></div><div class="section-head"><h2>Reference shelf</h2></div><p class="small muted">Official sources establish publication scope and chronology methods. Community sources provide chapter and event indexing. Inherited source citations are retained as provenance, not represented as fresh verification of every claim.</p><div class="grid wide">${data.sources.filter(s=>(s.reveal||0)<=model.gate).map(s=>`<article class="card source"><small>${esc(s.type||s.quality||'Reference')}</small><h3 style="font-size:19px">${external(s.url,s.title||s.id||'Source')}</h3><p>${esc(s.use||s.note||'Used for the new research extension.')}</p></article>`).join('')}</div><div class="notice">${esc(data.meta.copyright)} Last editorial update: ${data.meta.date}. <span id="validation-summary">${esc(data.validation?.summary||'Structural checks are run before deployment.')} ${esc(data.validation?.visual||'')}</span></div>`;
}
function searchView(){const q=$('search').value.trim(),list=model.search(q);return head('SEARCH THE SAFE ARCHIVE',q?`Results for “${q}”`:'Search the archive','Results include only records, event text and chapter context permitted by the selected completed-book boundary.')+`<div class="count" style="margin-bottom:20px">${list.length} results</div>`+paginate(list,x=>x.length?`<div class="grid">${x.map(r=>`<article class="card linked"><div class="type">${esc(r.kind)}</div><h3><a href="${r.href}">${esc(r.title)}</a></h3><p>${esc(trim(r.summary,200))}</p></article>`).join('')}</div>`:empty());}
function locators(e){
 if(!e.book)return '';
 const text=e.chapter||e.locator||'';
 const nums=[...String(text).matchAll(/\d+/g)].map(x=>Number(x[0]));
 const interlude=String(text).match(/Interlude\s+(\d+)/i);
 const num=interlude?data.chapters.find(c=>c.book===e.book&&c.interludeNumber===Number(interlude[1]))?.number:/postlude/i.test(text)?data.chapters.find(c=>c.book===e.book&&/^Postlude/i.test(c.label))?.number:/epilogue/i.test(text)?data.chapters.find(c=>c.book===e.book&&/^Epilogue/i.test(c.label))?.number:/prologue/i.test(text)?data.chapters.find(c=>c.book===e.book&&/^Prologue/i.test(c.label))?.number:nums[0];
 return `<div class="notice"><strong>Text locator:</strong> ${esc(e.book)} · ${num!==undefined&&model.chapterMap.has(e.book+':'+num)?`<a href="${chapterHref(e.book,num)}" class="external">${esc(text||'Chapter '+num)} →</a>`:esc(text||'Exact chapter not verified')}<div class="small muted">A range or unverified locator is not an assertion of an exact scene.</div></div>`;
}
function sourceLinks(items){return items.length?`<h2>Sources</h2><div class="links">${items.map((s,i)=>{if(typeof s==='string'){const found=data.sources.find(x=>x.id===s);return external(found?.url||s,found?.title||`Source ${i+1}`)}return external(s.url,s.title||s.label||`Source ${i+1}`)}).join(' ')}</div>`:'';}
function detailContent(type,id){
 if(type==='event'){
  const e=model.eventMap.get(id);if(!e||e.reveal>model.gate)return locked();
  return `<div class="eyebrow">${esc(e.book||'HISTORY')} · STORY ANCHOR</div><h1 id="detail-title">${esc(e.title)}</h1><div class="meta-line">${badge(e.confidence||'uncertain','gold')}</div><p style="margin-top:22px">${esc(e.summary)}</p>${e.explanation?`<p>${esc(e.explanation)}</p>`:''}${locators(e)}<h2>Chronology</h2><p>${esc(e.dateLabel||'Date not verified')}</p><div class="notice">${esc(e.chronology||'Relative anchor; exact synchronization is uncertain.')}</div><h2>Related entities</h2><div class="links">${links(e.characters,'character')}${links(e.locations,'location')}${links(e.factions,'faction')}</div><p class="coverage-note">${esc(e.provenance||'Curated event anchor.')}</p>${sourceLinks(e.sources||[])}`;
 }
 const p=model.profile(type+':'+id);if(!p)return locked();
 const edges=model.connections(p.key);
 return `<div class="eyebrow">${esc(p.type)}${p.full?' · '+esc(p.raw.kind||p.raw.category||'REFERENCE RECORD'):''}</div><h1 id="detail-title">${esc(p.name)}</h1><div class="actions"><button class="btn ${state.saved.has(p.key)?'primary':'ghost'}" data-bookmark="${p.key}">${state.saved.has(p.key)?'★ Bookmarked':'☆ Bookmark'}</button><button class="btn ghost" data-connect="${p.key}">View connections</button></div><p style="margin-top:22px">${esc(p.summary)}</p>${p.full&&p.raw.watSummary&&p.raw.watSummary!==p.summary?`<p>${esc(p.raw.watSummary)}</p>`:''}${!p.full?'<div class="notice">This profile uses safe dated facts only. Its broader summary, aliases and associations remain hidden until their source-book boundary.</div>':''}${p.full&&p.raw.aliases?.length?`<div class="small muted">Also known as ${esc(p.raw.aliases.join(', '))}</div>`:''}${p.facts.length?`<h2>Status through ${esc(boundaryName())}</h2><ol class="facts">${p.facts.map(f=>`<li>${esc(f.text)}${f.certainty&&f.certainty!=='confirmed'?' '+badge(f.certainty,'warn'):''}<span class="ref">${esc(f.locator||f.chapter||'Book-level fact; exact chapter unverified')}</span></li>`).join('')}</ol>`:'<div class="notice">No independently dated status transition is recorded. Profile associations do not establish a current status.</div>'}${p.full&&p.raw.limits?.length?`<h2>Rules & limits</h2><ul class="facts">${p.raw.limits.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}${p.full&&p.raw.goals?.length?`<h2>Recorded goals</h2><ul class="facts">${p.raw.goals.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}${p.events.length?`<h2>Book & chapter anchors</h2><div class="rows">${p.events.map(e=>`<a class="row" href="${entityHref('event',e.id)}"><div class="grow"><b>${esc(e.title)}</b><small>${esc(e.book||'History')} · ${esc(e.chapter||e.dateLabel)}</small></div><span class="arrow">→</span></a>`).join('')}</div>`:''}${edges.length?`<h2>Related records</h2><div class="links">${edges.map(e=>`<a class="entity-link" href="${href(e.target)}">${esc(e.target.name)} · ${esc(e.label)}</a>`).join('')}</div>`:''}${sourceLinks(p.sources)}<h2>Your note</h2><textarea id="entity-note" class="field" data-note="${p.key}" aria-label="Private note for ${esc(p.name)}" placeholder="A reminder for your next reading…">${esc(state.notes[p.key]||'')}</textarea><p class="coverage-note">Saved in this browser. Notes for later records are hidden by the spoiler boundary.</p>`;
}
function locked(){return `<div class="eyebrow">REFERENCE UNAVAILABLE</div><h1 id="detail-title">Beyond this boundary.</h1><p>This record is hidden at your current completed-book boundary, or the link is unknown. Choose a completed book above to reveal available details.</p>`;}
function chapterDetail(book,num){
 const c=model.chapterMap.get(book+':'+num);if(!c||c.reveal>model.gate)return locked();
 const all=data.chapters.filter(x=>x.book===book).sort((a,b)=>a.number-b.number),i=all.findIndex(x=>x.key===c.key),events=(c.anchors||[]).map(id=>model.eventMap.get(id)).filter(e=>e&&e.reveal<=model.gate);
 return `<div class="eyebrow">${esc(bookName(book))}</div><h1 id="detail-title">${esc(c.label)}</h1><div class="actions"><button class="btn ${state.read.has(c.key)?'primary':''}" data-read="${esc(c.key)}">${state.read.has(c.key)?'✓ Marked read':'○ Mark read'}</button>${all[i-1]?`<a class="btn ghost" href="${chapterHref(book,all[i-1].number)}">← Previous</a>`:''}${all[i+1]?`<a class="btn ghost" href="${chapterHref(book,all[i+1].number)}">Next →</a>`:''}</div><h2>${esc(c.arc||'Chapter context')}</h2><p>${esc(c.arcSummary||'No scene recap is recorded for this section.')}</p><div class="notice"><strong>${esc(c.coverage||'Chapter index')}</strong>${c.arcRange?'<br>Context range: '+esc(c.arcRange):''}<br>Arc context can cover multiple chapters. It is not a scene-by-scene synopsis of this section.</div>${events.length?`<h2>Story anchors</h2><div class="rows">${events.map(e=>`<a class="row" href="${entityHref('event',e.id)}"><b>${esc(e.title)}</b></a>`).join('')}</div>`:'<p class="small muted">No event anchor has been attached to this section.</p>'}${c.source||c.sourceUrl?`<h2>Reference</h2>${external(c.source||c.sourceUrl,'Chapter source — external spoilers may apply')}`:''}`;
}
let currentView='home',baseView='home',toastTimer;
function toast(s){$('toast').textContent=s;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2200);}
function persist(k,v){if(!store.set(k,v))toast('Browser storage unavailable. Export a reading backup to keep your changes.');}
function closePanel(){if(location.hash.startsWith('#/entity/')||location.hash.startsWith('#/chapter/'))location.hash='#/'+baseView;else hidePanel();}
function hidePanel(){const wasOpen=!$('detail').hidden;$('detail').hidden=true;$('veil').hidden=true;document.body.style.overflow='';if(wasOpen&&state.returnFocus?.isConnected)state.returnFocus.focus();}
function showPanel(content){if($('detail').hidden)state.returnFocus=document.activeElement;$('detail').innerHTML=`<div class="detail-top"><span class="small muted">STORMLIGHT ATLAS</span><button class="close" data-close aria-label="Close reference">×</button></div>${content}`;$('detail').hidden=false;$('veil').hidden=false;document.body.style.overflow='hidden';$('detail').setAttribute('aria-labelledby','detail-title');$('detail').scrollTop=0;$('detail').querySelector('[data-close]')?.focus();}
function render(){
 const raw=(location.hash.slice(2)||'home').split('?'),parts=raw[0].split('/').map(x=>{try{return decodeURIComponent(x)}catch{return x}}),params=new URLSearchParams(raw[1]);
 let view=parts[0];currentView=view;
 if(view==='entity'||view==='chapter'){
  if(!$('main').querySelector('section,article,header'))$('main').innerHTML=home();
  showPanel(view==='entity'?detailContent(parts[1],parts.slice(2).join('/')):chapterDetail(parts[1],parts[2]));return;
 }
 hidePanel();
 if(!titles[view]&&view!=='search')view='home';baseView=view;
 document.querySelectorAll('[data-nav]').forEach(x=>x.classList.toggle('active',x.dataset.nav===view));$('mobile-view').value=titles[view]?view:'explore';
 const builders={home,explore:()=>explorer(params),timeline,chapters:()=>chapterList(params),map:mapView,connections,status:statusLedger,saved,sources,search:searchView};
 $('main').innerHTML=builders[view]();document.title=`${titles[view]||'Search'} · Stormlight Atlas`;
}
$('boundary').innerHTML=`<option value="0">No books yet</option>`+data.books.map(b=>`<option value="${b.gate}">${esc(b.title)}</option>`).join('');$('boundary').value=String(model.gate);
$('boundary').addEventListener('change',()=>{model.gate=Number($('boundary').value);persist('gate',model.gate);state.book='all';state.page=1;state.query='';state.route='';state.relationKind='all';render();toast('Spoiler boundary updated to '+boundaryName());});
$('mobile-view').addEventListener('change',e=>{location.hash='#/'+e.target.value;});
$('search').addEventListener('input',()=>{state.page=1;if(location.hash!=='#/search')location.hash='#/search';else render();});
window.addEventListener('hashchange',()=>{state.page=1;render();});
document.addEventListener('click',e=>{
 const el=e.target.closest('button,[data-export]');if(!el)return;
 if(el.hasAttribute('data-close'))closePanel();
 if(el.dataset.type){state.type=el.dataset.type;state.page=1;history.replaceState(null,'','#/explore');render();}
 if(el.dataset.page){state.page=Number(el.dataset.page);render();window.scrollTo({top:0,behavior:'smooth'});}
 if(el.dataset.chapterBook){state.chapterBook=el.dataset.chapterBook;state.chapterQuery='';state.onlyAnchors=false;history.replaceState(null,'','#/chapters?book='+state.chapterBook);render();}
 if(el.dataset.read){const k=el.dataset.read;state.read.has(k)?state.read.delete(k):state.read.add(k);persist('read',[...state.read]);render();}
 if(el.dataset.bookmark){const k=el.dataset.bookmark;state.saved.has(k)?state.saved.delete(k):state.saved.add(k);persist('saved',[...state.saved]);render();}
 if(el.dataset.connect){state.focus=el.dataset.connect;state.relationKind='all';location.hash='#/connections';}
 if(el.hasAttribute('data-export')){const blob=new Blob([JSON.stringify({schema:'stormlight-reading-v3',gate:model.gate,read:[...state.read],saved:[...state.saved],notes:state.notes},null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='stormlight-reading-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
});
document.addEventListener('change',async e=>{
 const el=e.target;
 const controls={'entity-book':['book'],'timeline-book':['book'],'timeline-mode':['mode'],'map-plane':['plane'],'map-book':['book'],'map-route':['route'],'connection-focus':['focus'],'relation-kind':['relationKind']};
 if(controls[el.id]){state[controls[el.id][0]]=el.value;state.page=1;render();}
 if(el.id==='map-labels'){state.mapAllLabels=el.checked;render();}
 if(el.id==='anchors-only'){state.onlyAnchors=el.checked;render();}
 if(el.id==='import-backup'&&el.files?.[0]){try{if(el.files[0].size>2e6)throw Error('Backup too large.');const d=JSON.parse(await el.files[0].text());if(d.schema!=='stormlight-reading-v3'||!Array.isArray(d.read)||!Array.isArray(d.saved)||!d.notes||typeof d.notes!=='object')throw Error('This is not a Stormlight reading backup.');state.read=new Set(d.read.filter(x=>model.chapterMap.has(x)));state.saved=new Set(d.saved.filter(x=>model.entities.has(x)));state.notes=Object.fromEntries(Object.entries(d.notes).filter(([k,v])=>model.entities.has(k)&&typeof v==='string').map(([k,v])=>[k,v.slice(0,20000)]));persist('read',[...state.read]);persist('saved',[...state.saved]);persist('notes',state.notes);render();toast('Reading backup imported. Spoiler boundary preserved.');}catch(err){toast(err.message);}}
});
document.addEventListener('input',e=>{
 const el=e.target;
 if(el.dataset.note){state.notes[el.dataset.note]=el.value;persist('notes',state.notes);return;}
 const controls={'entity-query':'query','timeline-query':'query','status-query':'query','chapter-query':'chapterQuery'};
 if(controls[el.id]){const id=el.id,pos=el.selectionStart;state[controls[id]]=el.value;state.page=1;render();const n=$(id);n?.focus();try{n?.setSelectionRange(pos,pos)}catch{}}
});
$('veil').addEventListener('click',closePanel);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('detail').hidden)closePanel();else if($('search').value){$('search').value='';location.hash='#/home';}}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('search').focus();}if(e.key==='Tab'&&!$('detail').hidden){const focusable=[...$('detail').querySelectorAll('a[href],button,textarea,input,select')],first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
render();

export {model,state,render,home,explorer,timeline,chapterList,mapView,connections,saved,sources,detailContent,chapterDetail};
